// Category A — mirrors TextField while borrowing color parsing/input behavior from React Aria.
import {
  ColorField as AriaColorField,
  Label,
  Input,
  Text,
  FieldError,
} from "react-aria-components";
import type {
  ColorFieldProps as AriaColorFieldProps,
  ValidationResult,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./ColorField.css";

type ColorFieldSize = ControlSize;

export interface ColorFieldProps extends Omit<AriaColorFieldProps, "className" | "children"> {
  /**
   * Size axis for input height, padding, and type.
   *
   * @default "medium"
   */
  size?: ColorFieldSize;
  /** Field label. */
  label?: string;
  /** Helper text below the input. */
  description?: string;
  /** Validation message shown when invalid. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Input placeholder. */
  placeholder?: string;
  /** Additional class. sd-color-field is always preserved. */
  className?: string;
  /** Passed to the underlying input DOM node. */
  ref?: Ref<HTMLInputElement>;
}

export function ColorField({
  size = "medium",
  label,
  description,
  errorMessage,
  contextualHelp,
  placeholder,
  className,
  ref,
  ...props
}: ColorFieldProps) {
  return (
    <AriaColorField
      {...props}
      className={className ? `sd-color-field ${className}` : "sd-color-field"}
    >
      {contextualHelp ? (
        <div className="sd-color-field__label-group">
          {label && <Label className={`sd-color-field__label sd-type-label-${roleSize(size)}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-color-field__label sd-type-label-${roleSize(size)}`}>{label}</Label>
      )}
      <Input
        ref={ref}
        data-size={size}
        placeholder={placeholder}
        className={`sd-color-field__input sd-type-body-${roleSize(size)}`}
      />
      {description && (
        <Text slot="description" className={`sd-color-field__description sd-type-caption-${roleSize(size)}`}>
          {description}
        </Text>
      )}
      <FieldError className={`sd-color-field__error sd-type-caption-${roleSize(size)}`}>{errorMessage}</FieldError>
    </AriaColorField>
  );
}

.sd-color-field {
  --sd-color-field-input-background-current: var(--sd-color-field-input-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-color-field-gap);
}
.sd-color-field[data-readonly] {
  --sd-color-field-input-background-current: var(--sd-color-field-input-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-color-field__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-color-field-label-group-gap);
}

.sd-color-field__label {
  padding-inline: var(--sd-color-field-text-padding-inline);
  color: var(--sd-color-field-label-foreground);
}

.sd-color-field__input {
  --sd-color-field-input-radius-current: var(--sd-color-field-input-radius-medium);
  width: 100%;
  background: var(--sd-color-field-input-background-current);
  color: var(--sd-color-field-input-foreground);
  border: var(--sd-color-field-input-border-width) solid var(--sd-color-field-input-border);
  border-radius: var(--sd-color-field-input-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  /* Suppress the UA focus outline — the component draws its own indicator below
     (`[data-focused]`: border-color + ring). Without this the browser stacks `outline: auto` on top
     of that ring, so the field shows TWO rings, and because `outline: auto` uses
     `-webkit-focus-ring-color` the extra one takes the OS accent colour — it renders orange on a Mac
     set to an orange accent, blue elsewhere. Every other field in the family already resets it;
     this was the last one left after TextField and Textarea were fixed. */
  outline: none;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-color-field__input::placeholder {
  color: var(--sd-color-field-input-placeholder);
}

.sd-color-field__input[data-size="x-small"] {
  --sd-color-field-input-radius-current: var(--sd-color-field-input-radius-x-small);
  height: var(--sd-color-field-input-height-x-small);
  padding-inline: var(--sd-color-field-input-padding-inline-x-small);
}
.sd-color-field__input[data-size="small"] {
  --sd-color-field-input-radius-current: var(--sd-color-field-input-radius-small);
  height: var(--sd-color-field-input-height-small);
  padding-inline: var(--sd-color-field-input-padding-inline-small);
}
.sd-color-field__input[data-size="medium"] {
  --sd-color-field-input-radius-current: var(--sd-color-field-input-radius-medium);
  height: var(--sd-color-field-input-height-medium);
  padding-inline: var(--sd-color-field-input-padding-inline-medium);
}
.sd-color-field__input[data-size="large"] {
  --sd-color-field-input-radius-current: var(--sd-color-field-input-radius-large);
  height: var(--sd-color-field-input-height-large);
  padding-inline: var(--sd-color-field-input-padding-inline-large);
}
.sd-color-field__input[data-size="x-large"] {
  --sd-color-field-input-radius-current: var(--sd-color-field-input-radius-x-large);
  height: var(--sd-color-field-input-height-x-large);
  padding-inline: var(--sd-color-field-input-padding-inline-x-large);
}

.sd-color-field__input[data-hovered] {
  border-color: var(--sd-color-field-input-border-hover);
}
.sd-color-field__input[data-focused] {
  border-color: var(--sd-color-field-input-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-color-field__input[data-invalid] {
  border-color: var(--sd-color-field-input-border-invalid);
}
.sd-color-field__input[data-invalid][data-focused] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-color-field-input-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-color-field__input[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-color-field__description {
  padding-inline: var(--sd-color-field-text-padding-inline);
  color: var(--sd-color-field-description-foreground);
}
.sd-color-field__error {
  padding-inline: var(--sd-color-field-text-padding-inline);
  color: var(--sd-color-field-error-foreground);
}
